import { RandomImpl } from "#base/scripts/random-pcg-32.js";
import { ParameterSpec } from "#base/scripts/voronoi-types.js";
import { VoronoiUtils } from "#base/scripts/voronoi-utils.js";
import continentSettings from "#base/scripts/voronoi_data/continents.mapconfig.js";
import {
	ContinentGenerator,
	continentGeneratorRulesSettings,
	continentGeneratorSchema,
} from "#base/scripts/voronoi_generators/continent-generator.js";
import {
	MapBaseSettings,
	MapSettingSchema,
	VoronoiMap,
	voronoiMapSchema,
} from "#base/scripts/voronoi_maps/map-common.js";

export interface VoronoiContinentsSettings extends MapBaseSettings {
	totalLandmassSize: number;
	minLandmassSize: number;
}

export const continentsSchema = {
	...voronoiMapSchema,
	totalLandmassSize: {
		label: "Total Landmass Size",
		description: "The total percentage of land to be taken up by the major landmasses.",
		default: 32,
		min: 20,
		max: 50,
		step: 0.25,
	},
	minLandmassSize: {
		label: "Minimum Landmass Size",
		description: "The minimum size a specific landmass can be.",
		default: 12,
		min: 5,
		max: 30,
		step: 0.25,
	},
};

export class VoronoiContinents extends VoronoiMap<VoronoiContinentsSettings> {
	private applyState: RandomImpl.RandomState | undefined;

	constructor() {
		const schema = VoronoiUtils.clone(continentGeneratorSchema);

		// Lock the landmass sizes so they can't be edited in the UI or saved since they are driven by the map type.
		(schema.landmass.children.data.size as ParameterSpec).locked = true;
		(schema.landmass.children.data.variance as ParameterSpec).locked = true;

		(schema.landmass.children.data.coastalIslands as ParameterSpec).unified = true;
		(schema.landmass.children.data.coastalIslandsMaxDistance as ParameterSpec).unified = true;
		(schema.landmass.children.data.coastalIslandsMinDistance as ParameterSpec).unified = true;
		(schema.landmass.children.data.coastalIslandsSize as ParameterSpec).unified = true;
		(schema.landmass.children.data.coastalIslandsSizeVariance as ParameterSpec).unified = true;
		(schema.landmass.children.data.erosionPercent as ParameterSpec).unified = true;
		(schema.landmass.children.data.erosionRandomness as ParameterSpec).unified = true;
		(schema.landmass.children.data.erosionTime as ParameterSpec).unified = true;

		const generator = new ContinentGenerator(schema, continentGeneratorRulesSettings);
		super(
			continentsSchema,
			generator,
			generator.getDefaultGeneratorSettings(),
			generator.getDefaultRuleSettings(),
			continentSettings,
		);
	}

	static getName(): string {
		return "Continents";
	}

	init(hexDims: float2) {
		this.applyState = undefined; // Clear random key on init()
		this.initInternal(hexDims);
	}

	applySettings() {
		const dims = this.m_hexDims;
		const generatorSettings = (this.getGenerator() as ContinentGenerator).getTypedSettings();
		const totalPlayers = this.getSettings().totalPlayers;
		const landmassCount = generatorSettings.landmass.length;
		const totalSize = this.m_settings.totalLandmassSize;
		const minSize = this.m_settings.minLandmassSize;

		// Adjust the total and min size slightly based on the amount of area likely to be taken up by landmass boundaries
		// This helps maintain consistency between map sizes since the oceans need to take up a larger percentage of smaller maps
		// to ensure landmasses are separated by ocean tiles.

		const tileCount = dims.x * dims.y;
		const avgDim = dims.x + dims.y / 2;
		const landmassSeparationWidth = 4;

		// total number of tiles expected to be lost to ensuring landmass separation
		const landmassSeparationTiles = avgDim * (landmassCount - 1) * landmassSeparationWidth;

		const usablePercentage = (tileCount - landmassSeparationTiles) / tileCount;
		const adjustedTotalSize = totalSize * usablePercentage;
		const adjustedMinSize = minSize * usablePercentage;

		let minTotalSize = adjustedMinSize * landmassCount;

		if (adjustedMinSize > adjustedTotalSize) {
			console.error(
				`Minimum landmass size of ${minSize} is too large to fit ${landmassCount} landmasses with less than ${totalSize} total size.`,
			);
			minTotalSize = adjustedTotalSize / landmassCount;
		}

		const remaining = adjustedTotalSize - minTotalSize;

		if (this.applyState == undefined) this.applyState = RandomImpl.getState();
		RandomImpl.setState(this.applyState);

		// Uniform random partition of n landmasses.
		const cuts = Array.from(
			{ length: landmassCount - 1 },
			(_value, index) => RandomImpl.fRand(`Landmass ${index + 1} Size Variance`) * remaining,
		);
		cuts.sort((a, b) => a - b);

		const landmassSizes: number[] = [];
		let prev = 0;
		for (const cut of cuts) {
			landmassSizes.push(cut - prev + adjustedMinSize);
			prev = cut;
		}
		landmassSizes.push(remaining - prev + adjustedMinSize);

		generatorSettings.landmass.forEach((value, index) => {
			value.size = landmassSizes[index];
			value.variance = 2;
		});

		VoronoiUtils.generateLocationsAroundCircle(2, 0.4, 0.6).forEach((location, index) => {
			generatorSettings.landmass[index].xPos = location.x;
			generatorSettings.landmass[index].yPos = location.y;
		});

		const finalTotalSize = generatorSettings.landmass.reduce((acc, cur) => acc + cur.size, 0);
		let remainder = 0;
		console.log(
			`Creating ${totalPlayers} player positions for ${generatorSettings.landmass.length} landmasses with ${finalTotalSize} totalSize...`,
		);
		for (const landmass of generatorSettings.landmass) {
			const sizeRatio = landmass.size / finalTotalSize;
			const playerAreas = totalPlayers * sizeRatio + remainder;
			landmass.playerAreas = Math.round(playerAreas);
			console.log(
				`  size ${landmass.size} / ${finalTotalSize} = sizeRatio of ${sizeRatio}. Assigning ${landmass.playerAreas} player areas.`,
			);
			remainder = playerAreas - landmass.playerAreas;
		}
	}

	override simulateInternal() {
		this.applySettings();
	}

	getSettingsConfig(): MapSettingSchema {
		return this.m_baseSchema;
	}

	getFilename(): string {
		return "continents.mapconfig.js";
	}
}
